/**
 * Generated by `createservice subscription.RegisterSubscriptionContextsService --type mutations`
 */

const { getLogger } = require('@open-condo/keystone/logging')
const { GQLCustomSchema } = require('@open-condo/keystone/schema')

const access = require('@condo/domains/subscription/access/RegisterSubscriptionContextsService')
const {
    SUBSCRIPTION_PAYMENT_TYPES,
} = require('@condo/domains/subscription/constants')
const { REGISTER_SUBSCRIPTION_CONTEXTS_ERRORS: ERRORS } = require('@condo/domains/subscription/constants/registerSubscriptionContextsErrors')
const {
    loadOrganizationOrThrow,
    resolveRequestedSubscriptionsOrThrow,
    validateBundle,
    createTrialBundle,
    createPaidBundle,
} = require('@condo/domains/subscription/utils/serverSchema/registerSubscriptionContexts')

const logger = getLogger('RegisterSubscriptionContextsService')

const RegisterSubscriptionContextsService = new GQLCustomSchema('RegisterSubscriptionContextsService', {
    types: [
        {
            access: true,
            type: `enum SubscriptionPaymentType { ${SUBSCRIPTION_PAYMENT_TYPES.join(' ')} }`,
        },
        {
            access: true,
            type: 'input RegisterSubscriptionContextsInput { dv: Int!, sender: SenderFieldInput!, organization: OrganizationWhereUniqueInput!, subscriptionPlanPricingRules: [SubscriptionPlanPricingRuleWhereUniqueInput!]!, paymentType: SubscriptionPaymentType!, isTrial: Boolean }',
        },
        {
            access: true,
            type: 'type RegisterSubscriptionContextsOutput { subscriptionContexts: [SubscriptionContext!]!, directPaymentUrl: String, multiPayment: MultiPayment }',
        },
    ],

    mutations: [
        {
            access: access.canRegisterSubscriptionContexts,
            schema: 'registerSubscriptionContexts(data: RegisterSubscriptionContextsInput!): RegisterSubscriptionContextsOutput',
            doc: {
                summary: 'Registers a subscription for an organization from one or more pricing rules (a bundle). For trials (isTrial=true) creates a status DONE SubscriptionContext for every plan whose trial is available (its own trialDays), skipping plans with no trial or an already used one. For paid subscriptions creates one Invoice with a row per pricing rule and one SubscriptionContext per pricing rule with status CREATED; when paymentType=card a MultiPayment and directPaymentUrl are also created.',
                errors: ERRORS,
            },
            resolver: async (parent, args, context) => {
                const { data } = args
                const {
                    dv,
                    sender,
                    organization: organizationInput,
                    subscriptionPlanPricingRules: pricingRuleInputs,
                    paymentType,
                    isTrial,
                } = data

                logger.info({ msg: 'Starting subscription registration', data: { organizationId: organizationInput.id, pricingRuleCount: pricingRuleInputs.length, paymentType, isTrial } })

                const organization = await loadOrganizationOrThrow(context, organizationInput.id)
                const subscriptions = await resolveRequestedSubscriptionsOrThrow(context, pricingRuleInputs)

                await validateBundle(context, { subscriptions, organization })

                if (isTrial) {
                    return await createTrialBundle(context, { subscriptions, organization, dv, sender })
                }

                return await createPaidBundle(context, { subscriptions, organization, paymentType, dv, sender })
            },
        },
    ],

})

module.exports = {
    RegisterSubscriptionContextsService,
    ERRORS,
}
